def pbRecallAndReplace(idxBattler, idxParty, randomReplacement = false, batonPass = false)
  @scene.pbRecall(idxBattler) if !@battlers[idxBattler].fainted?
  @battlers[idxBattler].pbAbilitiesOnSwitchOut   # Inc. primordial weather check
  @scene.pbShowPartyLineup(idxBattler & 1) if pbSideSize(idxBattler) == 1
  pbMessagesOnReplace(idxBattler, idxParty) if !randomReplacement
  pbReplace(idxBattler, idxParty, batonPass)
end

def pbSendOut(sendOuts, startBattle = false)
  sendOuts.each { |b| @peer.pbOnEnteringBattle(self, @battlers[b[0]], b[1]) }
  @scene.pbSendOutBattlers(sendOuts, startBattle)
  sendOuts.each do |b|
    @scene.pbResetCommandsIndex(b[0])
    pbSetSeen(@battlers[b[0]])
    @usedInBattle[b[0] & 1][b[0] / 2] = true
  end
end

def pbCommandPhase
  @command_phase = true
  @scene.pbBeginCommandPhase
  # Reset choices if commands can be shown
  @battlers.each_with_index do |b, i|
    next if !b
    pbClearChoice(i) if pbCanShowCommands?(i)
  end
  # Reset choices to perform Mega Evolution if it wasn't done somehow
  2.times do |side|
    @megaEvolution[side].each_with_index do |megaEvo, i|
      @megaEvolution[side][i] = -1 if megaEvo >= 0
    end
  end
  # Choose actions for the round (player first, then AI)
  pbCommandPhaseLoop(true)    # Player chooses their actions
  if @decision != 0   # Battle ended, stop choosing actions
    @command_phase = false
    return
  end
  pbCommandPhaseLoop(false)   # AI chooses their actions
  @command_phase = false
end

def pbRegisterMegaEvolution(idxBattler)
  side  = @battlers[idxBattler].idxOwnSide
  owner = pbGetOwnerIndexFromBattlerIndex(idxBattler)
  @megaEvolution[side][owner] = idxBattler
end

def pbUnregisterMegaEvolution(idxBattler)
  side  = @battlers[idxBattler].idxOwnSide
  owner = pbGetOwnerIndexFromBattlerIndex(idxBattler)
  @megaEvolution[side][owner] = -1 if @megaEvolution[side][owner] == idxBattler
end

def pbToggleRegisteredMegaEvolution(idxBattler)
  side  = @battlers[idxBattler].idxOwnSide
  owner = pbGetOwnerIndexFromBattlerIndex(idxBattler)
  if @megaEvolution[side][owner] == idxBattler
    @megaEvolution[side][owner] = -1
  else
    @megaEvolution[side][owner] = idxBattler
  end
end

def pbFaint(showMessage = true)
  if !fainted?
    PBDebug.log("!!!***Can't faint with HP greater than 0")
    return
  end
  return if @fainted   # Has already fainted properly
  @battle.pbDisplayBrief(_INTL("{1} fainted!", pbThis)) if showMessage
  PBDebug.log("[Pokémon fainted] #{pbThis} (#{@index})") if !showMessage
  @battle.scene.pbFaintBattler(self)
  @battle.pbSetDefeated(self) if opposes?
  pbInitEffects(false)
  # Reset status
  self.status      = :NONE
  self.statusCount = 0
  # Lose happiness
  if @pokemon && @battle.internalBattle
    badLoss = @battle.allOtherSideBattlers(@index).any? { |b| b.level >= self.level + 30 }
    @pokemon.changeHappiness((badLoss) ? "faintbad" : "faint")
  end
  # Reset form
  @battle.peer.pbOnLeavingBattle(@battle, @pokemon, @battle.usedInBattle[idxOwnSide][@index / 2])
  @pokemon.makeUnmega if mega?
  @pokemon.makeUnprimal if primal?
  # Do other things
  @battle.pbClearChoice(@index)   # Reset choice
  pbOwnSide.effects[PBEffects::LastRoundFainted] = @battle.turnCount
  if $game_temp.party_direct_damage_taken &&
     $game_temp.party_direct_damage_taken[@pokemonIndex] &&
     pbOwnedByPlayer?
    $game_temp.party_direct_damage_taken[@pokemonIndex] = 0
  end
  # Check other battlers' abilities that trigger upon a battler fainting
  pbAbilitiesOnFainting
  # Check for end of primordial weather
  @battle.pbEndPrimordialWeather
end

def pbAbilitiesOnSwitchOut
  if abilityActive?
    Battle::AbilityEffects.triggerOnSwitchOut(self.ability, self, false)
  end
  # Reset form
  @battle.peer.pbOnLeavingBattle(@battle, @pokemon, @battle.usedInBattle[idxOwnSide][@index / 2])
  # Check for end of Neutralizing Gas/Unnerve
  if hasActiveAbility?(:NEUTRALIZINGGAS)
    # Treat self as fainted
    @hp = 0
    @fainted = true
    pbAbilitiesOnNeutralizingGasEnding
  elsif hasActiveAbility?([:UNNERVE, :ASONECHILLINGNEIGH, :ASONEGRIMNEIGH])
    # Treat self as fainted
    @hp = 0
    @fainted = true
    pbItemsOnUnnerveEnding
  end
  # Treat self as fainted
  @hp = 0
  @fainted = true
  # Check for end of primordial weather
  @battle.pbEndPrimordialWeather
end

def pbInitialize(pkmn, idxParty, batonPass = false)
  pbInitPokemon(pkmn, idxParty)
  pbInitEffects(batonPass)
  @damageState.reset
end

def pbInitPokemon(pkmn, idxParty)
  raise _INTL("An egg can't be an active Pokémon.") if pkmn.egg?
  @name         = pkmn.name
  @species      = pkmn.species
  @form         = pkmn.form
  @level        = pkmn.level
  @hp           = pkmn.hp
  @totalhp      = pkmn.totalhp
  @types        = pkmn.types
  @ability_id   = pkmn.ability_id
  @item_id      = pkmn.item_id
  @attack       = pkmn.attack
  @defense      = pkmn.defense
  @spatk        = pkmn.spatk
  @spdef        = pkmn.spdef
  @speed        = pkmn.speed
  @status       = pkmn.status
  @statusCount  = pkmn.statusCount
  @pokemon      = pkmn
  @pokemonIndex = idxParty
  @participants = []   # Participants earn Exp. if this battler is defeated
  @moves        = []
  pkmn.moves.each_with_index do |m, i|
    @moves[i] = Battle::Move.from_pokemon_move(@battle, m)
  end
end

def pbUpdate(fullChange = false)
  return if !@pokemon
  @pokemon.calc_stats
  @level          = @pokemon.level
  @hp             = @pokemon.hp
  @totalhp        = @pokemon.totalhp
  if !@effects[PBEffects::Transform]
    @attack       = @pokemon.attack
    @defense      = @pokemon.defense
    @spatk        = @pokemon.spatk
    @spdef        = @pokemon.spdef
    @speed        = @pokemon.speed
    if fullChange
      @types      = @pokemon.types
      @ability_id = @pokemon.ability_id
    end
  end
end
